content.content:
1	:root {
2	  --bg: #f7f7f4;
3	  --surface: #fffdf9;
4	  --surface-2: #f1f1ec;
5	  --ink: #14181c;
6	  --ink-muted: #5a656c;
7	  --ink-faint: #7a848a;
8	  --line: #dcded7;
9	  --line-strong: #c7cbc3;
10	  --accent: #0f766e;
11	  --accent-strong: #0b5d56;
12	  --accent-soft: #e6f2ef;
13	  --accent-line: #b7d6d0;
14	  --code-bg: #14181c;
15	  --code-ink: #e8ece8;
16	  --code-muted: #97a6a2;
17	  --warn: #8a5a12;
18	  --warn-soft: #fbf1dc;
19	  --warn-line: #e7d4ae;
20	  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", "Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", Georgia, serif;
21	  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
22	  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
23	  --radius: 10px;
24	  --radius-sm: 6px;
25	  --shadow: 0 1px 2px rgba(20, 24, 28, 0.04), 0 6px 20px rgba(20, 24, 28, 0.05);
26	  --wrap: 1080px;
27	}
28	
29	*,
30	*::before,
31	*::after {
32	  box-sizing: border-box;
33	}
34	
35	html {
36	  -webkit-text-size-adjust: 100%;
37	  scroll-behavior: smooth;
38	}
39	
40	body {
41	  margin: 0;
42	  background: var(--bg);
43	  color: var(--ink);
44	  font-family: var(--sans);
45	  font-size: 16px;
46	  line-height: 1.7;
47	  text-rendering: optimizeLegibility;
48	  -webkit-font-smoothing: antialiased;
49	}
50	
51	img,
52	svg {
53	  max-width: 100%;
54	}
55	
56	a {
57	  color: var(--accent-strong);
58	  text-decoration-thickness: 1px;
59	  text-underline-offset: 3px;
60	}
61	
62	a:hover {
63	  color: var(--accent);
64	}
65	
66	:focus-visible {
67	  outline: 2px solid var(--accent);
68	  outline-offset: 3px;
69	  border-radius: 3px;
70	}
71	
72	h1,
73	h2,
74	h3,
75	h4 {
76	  font-family: var(--serif);
77	  font-weight: 600;
78	  line-height: 1.25;
79	  letter-spacing: -0.01em;
80	  margin: 0 0 0.5em;
81	}
82	
83	p {
84	  margin: 0 0 1em;
85	}
86	
87	code {
88	  font-family: var(--mono);
89	  font-size: 0.9em;
90	  background: var(--surface-2);
91	  border: 1px solid var(--line);
92	  border-radius: 4px;
93	  padding: 0.05em 0.35em;
94	}
95	
96	[hidden] {
97	  display: none !important;
98	}
99	
100	.visually-hidden {
101	  position: absolute !important;
102	  width: 1px;
103	  height: 1px;
104	  margin: -1px;
105	  padding: 0;
106	  overflow: hidden;
107	  clip: rect(0 0 0 0);
108	  clip-path: inset(50%);
109	  white-space: nowrap;
110	  border: 0;
111	}
112	
113	.skip-link {
114	  position: absolute;
115	  left: 1rem;
116	  top: -3rem;
117	  z-index: 100;
118	  background: var(--ink);
119	  color: #fff;
120	  padding: 0.6rem 1rem;
121	  border-radius: var(--radius-sm);
122	  text-decoration: none;
123	  transition: top 0.15s ease;
124	}
125	
126	.skip-link:focus {
127	  top: 1rem;
128	  color: #fff;
129	}
130	
131	.wrap {
132	  width: min(100% - 2.5rem, var(--wrap));
133	  margin-inline: auto;
134	}
135	
136	/* Header */
137	
138	.site-header {
139	  position: sticky;
140	  top: 0;
141	  z-index: 20;
142	  background: rgba(247, 247, 244, 0.92);
143	  backdrop-filter: blur(8px);
144	  border-bottom: 1px solid var(--line);
145	}
146	
147	.nav {
148	  display: flex;
149	  align-items: center;
150	  justify-content: space-between;
151	  gap: 1rem;
152	  min-height: 58px;
153	}
154	
155	.wordmark {
156	  font-family: var(--serif);
157	  font-size: 1.16rem;
158	  font-weight: 600;
159	  letter-spacing: -0.015em;
160	  color: var(--ink);
161	  text-decoration: none;
162	  white-space: nowrap;
163	}
164	
165	.wordmark::after {
166	  content: "";
167	  display: inline-block;
168	  width: 6px;
169	  height: 6px;
170	  margin-left: 6px;
171	  border-radius: 50%;
172	  background: var(--accent);
173	  vertical-align: 0.32em;
174	}
175	
176	.nav-links {
177	  display: flex;
178	  align-items: center;
179	  gap: 0.25rem;
180	  margin: 0;
181	  padding: 0.35rem 0;
182	  list-style: none;
183	  overflow-x: auto;
184	  scrollbar-width: none;
185	  -webkit-overflow-scrolling: touch;
186	}
187	
188	.nav-links::-webkit-scrollbar {
189	  display: none;
190	}
191	
192	.nav-links a {
193	  display: inline-block;
194	  padding: 0.25rem 0.65rem;
195	  border-radius: var(--radius-sm);
196	  color: var(--ink-muted);
197	  font-size: 0.92rem;
198	  text-decoration: none;
199	  white-space: nowrap;
200	}
201	
202	.nav-links a:hover {
203	  color: var(--accent-strong);
204	  background: var(--accent-soft);
205	}
206	
207	/* Hero */
208	
209	.hero {
210	  padding: 4.5rem 0 3.25rem;
211	  border-bottom: 1px solid var(--line);
212	}
213	
214	.eyebrow {
215	  margin: 0 0 1rem;
216	  font-size: 0.78rem;
217	  font-weight: 600;
218	  letter-spacing: 0.14em;
219	  text-transform: uppercase;
220	  color: var(--accent);
221	}
222	
223	.hero h1 {
224	  font-size: clamp(2.65rem, 6.5vw, 4.25rem);
225	  line-height: 1.05;
226	  margin: 0 0 0.35rem;
227	  letter-spacing: -0.025em;
228	}
229	
230	.hero-subtitle {
231	  font-family: var(--serif);
232	  font-size: clamp(1.15rem, 2.4vw, 1.5rem);
233	  color: var(--ink);
234	  margin: 0 0 1.1rem;
235	}
236	
237	.hero-lede {
238	  max-width: 46rem;
239	  color: var(--ink-muted);
240	  font-size: 1.02rem;
241	  margin: 0;
242	}
243	
244	.hero-stats {
245	  display: grid;
246	  grid-template-columns: repeat(4, minmax(0, 1fr));
247	  gap: 0;
248	  margin: 2.6rem 0 0;
249	  border: 1px solid var(--line);
250	  border-radius: var(--radius);
251	  background: var(--surface);
252	  box-shadow: var(--shadow);
253	  overflow: hidden;
254	}
255	
256	.hero-stat {
257	  padding: 1.05rem 1.25rem;
258	  border-right: 1px solid var(--line);
259	}
260	
261	.hero-stat:last-child {
262	  border-right: 0;
263	}
264	
265	.hero-stat dt {
266	  margin: 0;
267	  font-family: var(--serif);
268	  font-size: 1.8rem;
269	  line-height: 1.15;
270	  color: var(--ink);
271	  font-variant-numeric: tabular-nums;
272	}
273	
274	.hero-stat dd {
275	  margin: 0.2rem 0 0;
276	  font-size: 0.82rem;
277	  color: var(--ink-faint);
278	}
279	
280	/* Sections */
281	
282	.section {
283	  padding: 3.5rem 0;
284	  border-bottom: 1px solid var(--line);
285	}
286	
287	.section:last-of-type {
288	  border-bottom: 0;
289	}
290	
291	.section-head {
292	  margin-bottom: 1.75rem;
293	}
294	
295	.section h2 {
296	  font-size: clamp(1.55rem, 3vw, 2rem);
297	  margin: 0 0 0.4rem;
298	}
299	
300	.section-lede {
301	  max-width: 42rem;
302	  color: var(--ink-muted);
303	  font-size: 0.96rem;
304	  margin: 0;
305	}
306	
307	/* Cards */
308	
309	.card-grid {
310	  display: grid;
311	  gap: 1rem;
312	}
313	
314	.card-grid-3 {
315	  grid-template-columns: repeat(3, minmax(0, 1fr));
316	}
317	
318	.panel {
319	  background: var(--surface);
320	  border: 1px solid var(--line);
321	  border-radius: var(--radius);
322	  padding: 1.3rem 1.35rem;
323	  box-shadow: var(--shadow);
324	}
325	
326	.panel h3 {
327	  font-size: 1.06rem;
328	  margin: 0 0 0.5rem;
329	}
330	
331	.panel p {
332	  margin: 0;
333	  color: var(--ink-muted);
334	  font-size: 0.92rem;
335	  line-height: 1.65;
336	}
337	
338	/* Workflow */
339	
340	.workflow-card {
341	  margin: 0;
342	  background: var(--surface);
343	  border: 1px solid var(--line);
344	  border-radius: var(--radius);
345	  box-shadow: var(--shadow);
346	  padding: 1rem;
347	}
348	
349	.workflow-scroll {
350	  overflow-x: auto;
351	  padding-bottom: 0.35rem;
352	  -webkit-overflow-scrolling: touch;
353	}
354	
355	.workflow-svg {
356	  display: block;
357	  width: 100%;
358	  min-width: 760px;
359	  height: auto;
360	}
361	
362	.flow-links line {
363	  stroke: var(--accent-line);
364	  stroke-width: 1.6;
365	}
366	
367	.flow-node rect {
368	  fill: var(--surface);
369	  stroke: var(--line-strong);
370	  stroke-width: 1.2;
371	}
372	
373	.flow-node-end rect {
374	  fill: var(--accent-soft);
375	  stroke: var(--accent-line);
376	}
377	
378	.flow-step {
379	  font-family: var(--sans);
380	  font-size: 11px;
381	  fill: var(--accent);
382	  letter-spacing: 0.08em;
383	}
384	
385	.flow-label {
386	  font-family: var(--sans);
387	  font-size: 14px;
388	  font-weight: 600;
389	  fill: var(--ink);
390	}
391	
392	.flow-node-end .flow-label {
393	  fill: var(--accent-strong);
394	}
395	
396	.flow-loop {
397	  opacity: 0.9;
398	}
399	
400	.flow-loop-label {
401	  font-family: var(--sans);
402	  font-size: 12px;
403	  fill: var(--ink-muted);
404	}
405	
406	/* Demo */
407	
408	.tabs {
409	  display: flex;
410	  gap: 0.25rem;
411	  overflow-x: auto;
412	  border-bottom: 1px solid var(--line);
413	  margin-bottom: 1.5rem;
414	  scrollbar-width: thin;
415	  -webkit-overflow-scrolling: touch;
416	}
417	
418	.tab {
419	  appearance: none;
420	  background: none;
421	  border: 0;
422	  border-bottom: 2px solid transparent;
423	  margin-bottom: -1px;
424	  padding: 0.6rem 0.85rem;
425	  font-family: var(--sans);
426	  font-size: 0.9rem;
427	  color: var(--ink-muted);
428	  white-space: nowrap;
429	  cursor: pointer;
430	}
431	
432	.tab:hover {
433	  color: var(--ink);
434	}
435	
436	.tab[aria-selected="true"] {
437	  color: var(--accent-strong);
438	  border-bottom-color: var(--accent);
439	  font-weight: 600;
440	}
441	
442	.demo-status {
443	  margin: 0 0 1.5rem;
444	  padding: 0.9rem 1.1rem;
445	  border: 1px solid var(--warn-line);
446	  border-radius: var(--radius-sm);
447	  background: var(--warn-soft);
448	  color: var(--warn);
449	  font-size: 0.92rem;
450	}
451	
452	.tab-panel {
453	  background: var(--surface);
454	  border: 1px solid var(--line);
455	  border-radius: var(--radius);
456	  box-shadow: var(--shadow);
457	  padding: 1.5rem;
458	}
459	
460	.case-question {
461	  font-family: var(--serif);
462	  font-size: clamp(1.15rem, 2.2vw, 1.4rem);
463	  line-height: 1.45;
464	  margin: 0 0 1.25rem;
465	}
466	
467	.plan {
468	  display: grid;
469	  gap: 0.9rem;
470	  margin-bottom: 1.5rem;
471	  padding-bottom: 1.4rem;
472	  border-bottom: 1px solid var(--line);
473	}
474	
475	.plan-group {
476	  display: flex;
477	  flex-wrap: wrap;
478	  align-items: baseline;
479	  gap: 0.4rem 0.45rem;
480	}
481	
482	.plan-label {
483	  font-size: 0.78rem;
484	  font-weight: 600;
485	  letter-spacing: 0.06em;
486	  color: var(--ink-faint);
487	  margin-right: 0.15rem;
488	}
489	
490	.chip {
491	  display: inline-flex;
492	  align-items: center;
493	  padding: 0.1rem 0.5rem;
494	  border-radius: 999px;
495	  border: 1px solid var(--line-strong);
496	  background: var(--surface-2);
497	  color: var(--ink-muted);
498	  font-size: 0.78rem;
499	  line-height: 1.6;
500	  white-space: nowrap;
501	}
502	
503	.chip-missing {
504	  background: var(--warn-soft);
505	  border-color: var(--warn-line);
506	  color: var(--warn);
507	}
508	
509	.coverage {
510	  display: flex;
511	  flex-wrap: wrap;
512	  align-items: center;
513	  gap: 0.6rem 1rem;
514	  margin-bottom: 1.75rem;
515	}
516	
517	.coverage-label {
518	  font-size: 0.82rem;
519	  font-weight: 600;
520	  color: var(--ink-muted);
521	}
522	
523	.progress {
524	  flex: 1 1 200px;
525	  height: 8px;
526	  border-radius: 999px;
527	  background: var(--surface-2);
528	  border: 1px solid var(--line);
529	  overflow: hidden;
530	}
531	
532	.progress-bar {
533	  display: block;
534	  height: 100%;
535	  background: var(--accent);
536	  border-radius: inherit;
537	  transition: width 0.35s ease;
538	}
539	
540	.coverage-value {
541	  font-family: var(--mono);
542	  font-size: 0.85rem;
543	  color: var(--ink);
544	  font-variant-numeric: tabular-nums;
545	}
546	
547	.coverage-missing {
548	  flex-basis: 100%;
549	  display: flex;
550	  flex-wrap: wrap;
551	  align-items: baseline;
552	  gap: 0.4rem;
553	  font-size: 0.82rem;
554	  color: var(--warn);
555	}
556	
557	/* Evidence */
558	
559	.evidence-list {
560	  display: grid;
561	  gap: 0.85rem;
562	  margin: 0 0 1rem;
563	  padding: 0;
564	  list-style: none;
565	}
566	
567	.evidence-card {
568	  border: 1px solid var(--line);
569	  border-left: 3px solid var(--accent-line);
570	  border-radius: var(--radius-sm);
571	  background: var(--surface);
572	  padding: 1rem 1.15rem;
573	}
574	
575	.evidence-head {
576	  display: flex;
577	  flex-wrap: wrap;
578	  align-items: baseline;
579	  gap: 0.45rem 0.6rem;
580	  margin-bottom: 0.3rem;
581	}
582	
583	.evidence-ordinal {
584	  font-family: var(--mono);
585	  font-size: 0.78rem;
586	  font-weight: 600;
587	  color: var(--accent);
588	  background: var(--accent-soft);
589	  border-radius: 4px;
590	  padding: 0.05rem 0.4rem;
591	}
592	
593	.evidence-title {
594	  font-family: var(--serif);
595	  font-size: 1rem;
596	  font-weight: 600;
597	  line-height: 1.4;
598	  margin: 0;
599	  flex: 1 1 16rem;
600	}
601	
602	.evidence-title a {
603	  color: inherit;
604	  text-decoration: none;
605	}
606	
607	.evidence-prov {
608	  margin: 0 0 0.65rem;
609	  font-size: 0.8rem;
610	  color: var(--ink-faint);
611	}
612	
613	.evidence-meta {
614	  display: flex;
615	  flex-wrap: wrap;
616	  gap: 0.35rem;
617	  margin-bottom: 0.7rem;
618	}
619	
620	.chip-score {
621	  font-family: var(--mono);
622	  background: var(--accent-soft);
623	  border-color: var(--accent-line);
624	  color: var(--accent-strong);
625	  font-variant-numeric: tabular-nums;
626	}
627	
628	.evidence-quote {
629	  margin: 0 0 0.5rem;
630	  padding: 0.55rem 0 0.55rem 0.9rem;
631	  border-left: 2px solid var(--line-strong);
632	  color: var(--ink-muted);
633	  font-size: 0.9rem;
634	  line-height: 1.7;
635	  white-space: pre-line;
636	  overflow-wrap: anywhere;
637	}
638	
639	.evidence-quote:last-child {
640	  margin-bottom: 0;
641	}
642	
643	.toggle-btn {
644	  appearance: none;
645	  background: none;
646	  border: 1px solid var(--line-strong);
647	  border-radius: var(--radius-sm);
648	  padding: 0.45rem 0.95rem;
649	  font-family: var(--sans);
650	  font-size: 0.85rem;
651	  color: var(--accent-strong);
652	  cursor: pointer;
653	}
654	
655	.toggle-btn:hover {
656	  background: var(--accent-soft);
657	  border-color: var(--accent-line);
658	}
659	
660	/* Gaps */
661	
662	.gaps {
663	  margin-top: 1.5rem;
664	  padding-top: 1.4rem;
665	  border-top: 1px solid var(--line);
666	}
667	
668	.gaps h3 {
669	  font-size: 0.95rem;
670	  margin: 0 0 0.6rem;
671	}
672	
673	.gaps-list {
674	  display: flex;
675	  flex-wrap: wrap;
676	  gap: 0.4rem;
677	  margin: 0 0 0.75rem;
678	  padding: 0;
679	  list-style: none;
680	}
681	
682	.gap-paper {
683	  font-size: 0.78rem;
684	  color: var(--ink-muted);
685	  background: var(--surface-2);
686	  border: 1px dashed var(--line-strong);
687	  border-radius: 999px;
688	  padding: 0.12rem 0.6rem;
689	}
690	
691	.gaps-note,
692	.empty-note {
693	  margin: 0;
694	  font-size: 0.85rem;
695	  color: var(--ink-faint);
696	}
697	
698	/* Corpus table */
699	
700	.table-card {
701	  background: var(--surface);
702	  border: 1px solid var(--line);
703	  border-radius: var(--radius);
704	  box-shadow: var(--shadow);
705	  overflow: hidden;
706	}
707	
708	.corpus-table {
709	  width: 100%;
710	  border-collapse: collapse;
711	  font-size: 0.9rem;
712	}
713	
714	.corpus-table caption {
715	  text-align: left;
716	}
717	
718	.corpus-table th,
719	.corpus-table td {
720	  padding: 0.8rem 1rem;
721	  text-align: left;
722	  vertical-align: top;
723	  border-bottom: 1px solid var(--line);
724	}
725	
726	.corpus-table thead th {
727	  background: var(--surface-2);
728	  font-family: var(--sans);
729	  font-size: 0.76rem;
730	  font-weight: 600;
731	  letter-spacing: 0.06em;
732	  color: var(--ink-faint);
733	  white-space: nowrap;
734	}
735	
736	.corpus-table tbody tr:last-child td {
737	  border-bottom: 0;
738	}
739	
740	.corpus-table tbody tr:hover {
741	  background: rgba(15, 118, 110, 0.03);
742	}
743	
744	.corpus-table td[data-label="论文"] {
745	  font-family: var(--serif);
746	  font-size: 0.95rem;
747	  line-height: 1.45;
748	  color: var(--ink);
749	}
750	
751	.tag-row {
752	  display: flex;
753	  flex-wrap: wrap;
754	  gap: 0.3rem;
755	}
756	
757	.tag {
758	  display: inline-block;
759	  font-size: 0.74rem;
760	  line-height: 1.6;
761	  padding: 0.02rem 0.45rem;
762	  border-radius: 999px;
763	  background: var(--accent-soft);
764	  color: var(--accent-strong);
765	  white-space: nowrap;
766	}
767	
768	/* Records */
769	
770	.records-grid {
771	  display: grid;
772	  grid-template-columns: repeat(3, minmax(0, 1fr));
773	  gap: 1rem;
774	  margin-bottom: 1rem;
775	}
776	
777	.record-card {
778	  background: var(--surface);
779	  border: 1px solid var(--line);
780	  border-radius: var(--radius);
781	  box-shadow: var(--shadow);
782	  padding: 1.15rem 1.25rem;
783	}
784	
