file.content:
:root {
  --bg: #f7f7f4;
  --surface: #fffdf9;
  --surface-2: #f1f1ec;
  --ink: #14181c;
  --ink-muted: #5a656c;
  --ink-faint: #7a848a;
  --line: #dcded7;
  --line-strong: #c7cbc3;
  --accent: #0f766e;
  --accent-strong: #0b5d56;
  --accent-soft: #e6f2ef;
  --accent-line: #b7d6d0;
  --code-bg: #14181c;
  --code-ink: #e8ece8;
  --code-muted: #97a6a2;
  --warn: #8a5a12;
  --warn-soft: #fbf1dc;
  --warn-line: #e7d4ae;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", "Songti SC", "Noto Serif CJK SC", "Source Han Serif SC", Georgia, serif;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --radius: 10px;
  --radius-sm: 6px;
  --shadow: 0 1px 2px rgba(20, 24, 28, 0.04), 0 6px 20px rgba(20, 24, 28, 0.05);
  --wrap: 1080px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.7;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  max-width: 100%;
}

a {
  color: var(--accent-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

a:hover {
  color: var(--accent);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 3px;
}

h1,
h2,
h3,
h4 {
  font-family: var(--serif);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
  margin: 0 0 0.5em;
}

p {
  margin: 0 0 1em;
}

code {
  font-family: var(--mono);
  font-size: 0.9em;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0.05em 0.35em;
}

[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  z-index: 100;
  background: var(--ink);
  color: #fff;
  padding: 0.6rem 1rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: top 0.15s ease;
}

.skip-link:focus {
  top: 1rem;
  color: #fff;
}

.wrap {
  width: min(100% - 2.5rem, var(--wrap));
  margin-inline: auto;
}

/* Header */

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(247, 247, 244, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 58px;
}

.wordmark {
  font-family: var(--serif);
  font-size: 1.16rem;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--ink);
  text-decoration: none;
  white-space: nowrap;
}

.wordmark::after {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-left: 6px;
  border-radius: 50%;
  background: var(--accent);
  vertical-align: 0.32em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin: 0;
  padding: 0.35rem 0;
  list-style: none;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.nav-links::-webkit-scrollbar {
  display: none;
}

.nav-links a {
  display: inline-block;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-sm);
  color: var(--ink-muted);
  font-size: 0.92rem;
  text-decoration: none;
  white-space: nowrap;
}

.nav-links a:hover {
  color: var(--accent-strong);
  background: var(--accent-soft);
}

/* Hero */

.hero {
  padding: 4.5rem 0 3.25rem;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 1rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
}

.hero h1 {
  font-size: clamp(2.65rem, 6.5vw, 4.25rem);
  line-height: 1.05;
  margin: 0 0 0.35rem;
  letter-spacing: -0.025em;
}

.hero-subtitle {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2.4vw, 1.5rem);
  color: var(--ink);
  margin: 0 0 1.1rem;
}

.hero-lede {
  max-width: 46rem;
  color: var(--ink-muted);
  font-size: 1.02rem;
  margin: 0;
}

.hero-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  margin: 2.6rem 0 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.hero-stat {
  padding: 1.05rem 1.25rem;
  border-right: 1px solid var(--line);
}

.hero-stat:last-child {
  border-right: 0;
}

.hero-stat dt {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.8rem;
  line-height: 1.15;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.hero-stat dd {
  margin: 0.2rem 0 0;
  font-size: 0.82rem;
  color: var(--ink-faint);
}

/* Sections */

.section {
  padding: 3.5rem 0;
  border-bottom: 1px solid var(--line);
}

.section:last-of-type {
  border-bottom: 0;
}

.section-head {
  margin-bottom: 1.75rem;
}

.section h2 {
  font-size: clamp(1.55rem, 3vw, 2rem);
  margin: 0 0 0.4rem;
}

.section-lede {
  max-width: 42rem;
  color: var(--ink-muted);
  font-size: 0.96rem;
  margin: 0;
}

/* Cards */

.card-grid {
  display: grid;
  gap: 1rem;
}

.card-grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.3rem 1.35rem;
  box-shadow: var(--shadow);
}

.panel h3 {
  font-size: 1.06rem;
  margin: 0 0 0.5rem;
}

.panel p {
  margin: 0;
  color: var(--ink-muted);
  font-size: 0.92rem;
  line-height: 1.65;
}

/* Workflow */

.workflow-card {
  margin: 0;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1rem;
}

.workflow-scroll {
  overflow-x: auto;
  padding-bottom: 0.35rem;
  -webkit-overflow-scrolling: touch;
}

.workflow-svg {
  display: block;
  width: 100%;
  min-width: 760px;
  height: auto;
}

.flow-links line {
  stroke: var(--accent-line);
  stroke-width: 1.6;
}

.flow-node rect {
  fill: var(--surface);
  stroke: var(--line-strong);
  stroke-width: 1.2;
}

.flow-node-end rect {
  fill: var(--accent-soft);
  stroke: var(--accent-line);
}

.flow-step {
  font-family: var(--sans);
  font-size: 11px;
  fill: var(--accent);
  letter-spacing: 0.08em;
}

.flow-label {
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 600;
  fill: var(--ink);
}

.flow-node-end .flow-label {
  fill: var(--accent-strong);
}

.flow-loop {
  opacity: 0.9;
}

.flow-loop-label {
  font-family: var(--sans);
  font-size: 12px;
  fill: var(--ink-muted);
}

/* Demo */

.tabs {
  display: flex;
  gap: 0.25rem;
  overflow-x: auto;
  border-bottom: 1px solid var(--line);
  margin-bottom: 1.5rem;
  scrollbar-width: thin;
  -webkit-overflow-scrolling: touch;
}

.tab {
  appearance: none;
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  padding: 0.6rem 0.85rem;
  font-family: var(--sans);
  font-size: 0.9rem;
  color: var(--ink-muted);
  white-space: nowrap;
  cursor: pointer;
}

.tab:hover {
  color: var(--ink);
}

.tab[aria-selected="true"] {
  color: var(--accent-strong);
  border-bottom-color: var(--accent);
  font-weight: 600;
}

.demo-status {
  margin: 0 0 1.5rem;
  padding: 0.9rem 1.1rem;
  border: 1px solid var(--warn-line);
  border-radius: var(--radius-sm);
  background: var(--warn-soft);
  color: var(--warn);
  font-size: 0.92rem;
}

.tab-panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5rem;
}

.case-question {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 2.2vw, 1.4rem);
  line-height: 1.45;
  margin: 0 0 1.25rem;
}

.plan {
  display: grid;
  gap: 0.9rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1.4rem;
  border-bottom: 1px solid var(--line);
}

.plan-group {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.4rem 0.45rem;
}

.plan-label {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
  margin-right: 0.15rem;
}

.chip {
  display: inline-flex;
  align-items: center;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: var(--surface-2);
  color: var(--ink-muted);
  font-size: 0.78rem;
  line-height: 1.6;
  white-space: nowrap;
}

.chip-missing {
  background: var(--warn-soft);
  border-color: var(--warn-line);
  color: var(--warn);
}

.coverage {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem 1rem;
  margin-bottom: 1.75rem;
}

.coverage-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-muted);
}

.progress {
  flex: 1 1 200px;
  height: 8px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  overflow: hidden;
}

.progress-bar {
  display: block;
  height: 100%;
  background: var(--accent);
  border-radius: inherit;
  transition: width 0.35s ease;
}

.coverage-value {
  font-family: var(--mono);
  font-size: 0.85rem;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.coverage-missing {
  flex-basis: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.4rem;
  font-size: 0.82rem;
  color: var(--warn);
}

/* Evidence */

.evidence-list {
  display: grid;
  gap: 0.85rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
}

.evidence-card {
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent-line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  padding: 1rem 1.15rem;
}

.evidence-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.45rem 0.6rem;
  margin-bottom: 0.3rem;
}

.evidence-ordinal {
  font-family: var(--mono);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 4px;
  padding: 0.05rem 0.4rem;
}

.evidence-title {
  font-family: var(--serif);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin: 0;
  flex: 1 1 16rem;
}

.evidence-title a {
  color: inherit;
  text-decoration: none;
}

.evidence-prov {
  margin: 0 0 0.65rem;
  font-size: 0.8rem;
  color: var(--ink-faint);
}

.evidence-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-bottom: 0.7rem;
}

.chip-score {
  font-family: var(--mono);
  background: var(--accent-soft);
  border-color: var(--accent-line);
  color: var(--accent-strong);
  font-variant-numeric: tabular-nums;
}

.evidence-quote {
  margin: 0 0 0.5rem;
  padding: 0.55rem 0 0.55rem 0.9rem;
  border-left: 2px solid var(--line-strong);
  color: var(--ink-muted);
  font-size: 0.9rem;
  line-height: 1.7;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.evidence-quote:last-child {
  margin-bottom: 0;
}

.toggle-btn {
  appearance: none;
  background: none;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  padding: 0.45rem 0.95rem;
  font-family: var(--sans);
  font-size: 0.85rem;
  color: var(--accent-strong);
  cursor: pointer;
}

.toggle-btn:hover {
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

/* Gaps */

.gaps {
  margin-top: 1.5rem;
  padding-top: 1.4rem;
  border-top: 1px solid var(--line);
}

.gaps h3 {
  font-size: 0.95rem;
  margin: 0 0 0.6rem;
}

.gaps-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0 0 0.75rem;
  padding: 0;
  list-style: none;
}

.gap-paper {
  font-size: 0.78rem;
  color: var(--ink-muted);
  background: var(--surface-2);
  border: 1px dashed var(--line-strong);
  border-radius: 999px;
  padding: 0.12rem 0.6rem;
}

.gaps-note,
.empty-note {
  margin: 0;
  font-size: 0.85rem;
  color: var(--ink-faint);
}

/* Corpus table */

.table-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.corpus-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

.corpus-table caption {
  text-align: left;
}

.corpus-table th,
.corpus-table td {
  padding: 0.8rem 1rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--line);
}

.corpus-table thead th {
  background: var(--surface-2);
  font-family: var(--sans);
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
  white-space: nowrap;
}

.corpus-table tbody tr:last-child td {
  border-bottom: 0;
}

.corpus-table tbody tr:hover {
  background: rgba(15, 118, 110, 0.03);
}

.corpus-table td[data-label="论文"] {
  font-family: var(--serif);
  font-size: 0.95rem;
  line-height: 1.45;
  color: var(--ink);
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.tag {
  display: inline-block;
  font-size: 0.74rem;
  line-height: 1.6;
  padding: 0.02rem 0.45rem;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong);
  white-space: nowrap;
}

/* Records */

.records-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 1rem;
}

.record-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.15rem 1.25rem;
}

.record-value {
  display: block;
  font-family: var(--serif);
  font-size: 2rem;
  line-height: 1.15;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.record-label {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.82rem;
  color: var(--ink-faint);
}

.records-note {
  font-size: 0.84rem;
  color: var(--ink-faint);
  margin: 0 0 2rem;
}

.memory-card {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.35rem 1.4rem;
}

.memory-card h3 {
  font-size: 0.95rem;
  margin: 0 0 0.55rem;
  color: var(--ink-muted);
}

.memory-question {
  font-family: var(--serif);
  font-size: 1.08rem;
  line-height: 1.5;
  color: var(--ink);
  margin: 0 0 1.15rem;
}

.memory-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
}

.memory-group h4 {
  font-family: var(--sans);
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--ink-faint);
  margin: 0 0 0.4rem;
}

.memory-group ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.memory-group li {
  position: relative;
  font-size: 0.86rem;
  color: var(--ink-muted);
  padding-left: 0.9rem;
  margin-bottom: 0.4rem;
  line-height: 1.55;
}

.memory-group li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.62em;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-line);
}

.memory-reading li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  padding-left: 0;
}

.memory-reading li::before {
  display: none;
}

.memory-reading .paper-name {
  flex: 1 1 auto;
  overflow-wrap: anywhere;
}

.read-state {
  flex: 0 0 auto;
  font-family: var(--mono);
  font-size: 0.7rem;
  padding: 0.02rem 0.4rem;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  color: var(--ink-faint);
  background: var(--surface);
}

.read-state[data-state="read"] {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent-strong);
}

.memory-empty {
  font-size: 0.84rem;
  color: var(--ink-faint);
  margin: 0;
}

/* Quick start */

.code-card {
  position: relative;
  background: var(--code-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.35rem 1.4rem;
  overflow: hidden;
}

.code-card pre {
  margin: 0;
  overflow-x: auto;
  scrollbar-width: thin;
}

.code-card code {
  display: block;
  background: none;
  border: 0;
  padding: 0;
  font-family: var(--mono);
  font-size: 0.87rem;
  line-height: 1.9;
  color: var(--code-ink);
  white-space: pre;
}

.copy-btn {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  appearance: none;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: var(--radius-sm);
  padding: 0.28rem 0.7rem;
  font-family: var(--sans);
  font-size: 0.76rem;
  color: var(--code-ink);
  cursor: pointer;
}

.copy-btn:hover {
  background: rgba(255, 255, 255, 0.16);
}

/* Boundaries */

.limits-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.75rem;
}

.limits-list li {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 1rem 1.15rem;
}

.limit-index {
  flex: 0 0 auto;
  font-family: var(--mono);
  font-size: 0.76rem;
  color: var(--accent);
  padding-top: 0.22rem;
  letter-spacing: 0.04em;
}

.limits-list p {
  margin: 0;
  font-size: 0.92rem;
  color: var(--ink-muted);
  line-height: 1.65;
}

/* Footer */

.site-footer {
  border-top: 1px solid var(--line);
  padding: 1.75rem 0 2.25rem;
  background: var(--bg);
}

.footer-inner p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ink-faint);
}

.footer-inner time {
  font-variant-numeric: tabular-nums;
}

/* Responsive */

@media (max-width: 900px) {
  .card-grid-3 {
    grid-template-columns: 1fr;
  }

  .memory-grid {
    grid-template-columns: 1fr;
    gap: 0.9rem;
  }

  .hero-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .hero-stat:nth-child(2) {
    border-right: 0;
  }

  .hero-stat:nth-child(-n + 2) {
    border-bottom: 1px solid var(--line);
  }
}

@media (max-width: 700px) {
  .section {
    padding: 2.75rem 0;
  }

  .hero {
    padding: 3.25rem 0 2.5rem;
  }

  .tab-panel {
    padding: 1.15rem;
  }

  .records-grid {
    grid-template-columns: 1fr;
    gap: 0.7rem;
  }

  .record-card {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.9rem 1.1rem;
  }

  .record-value {
    font-size: 1.55rem;
  }

  .record-label {
    margin-top: 0;
  }

  .workflow-card {
    padding: 0.75rem;
  }

  /* Table becomes stacked cards */
  .table-card {
    background: none;
    border: 0;
    box-shadow: none;
    overflow: visible;
  }

  .corpus-table,
  .corpus-table tbody,
  .corpus-table tr,
  .corpus-table td {
    display: block;
    width: 100%;
  }

  .corpus-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .corpus-table tbody tr {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 0.9rem 1.05rem;
    margin-bottom: 0.7rem;
  }

  .corpus-table tbody tr:hover {
    background: var(--surface);
  }

  .corpus-table td {
    display: grid;
    grid-template-columns: 5.5rem minmax(0, 1fr);
    gap: 0.6rem;
    padding: 0.28rem 0;
    border-bottom: 0;
    font-size: 0.87rem;
  }

  .corpus-table td::before {
    content: attr(data-label);
    font-size: 0.74rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    color: var(--ink-faint);
    padding-top: 0.12rem;
  }

  .corpus-table td[data-label="论文"] {
    font-size: 1rem;
    padding-bottom: 0.45rem;
  }
}

@media (max-width: 560px) {
  .wrap {
    width: min(100% - 1.75rem, var(--wrap));
  }

  .nav {
    gap: 0.5rem;
  }

  .hero h1 {
    font-size: clamp(2.35rem, 12vw, 3rem);
  }

  .hero-stats {
    margin-top: 2rem;
  }

  .hero-stat {
    padding: 0.85rem 1rem;
  }

  .hero-stat dt {
    font-size: 1.5rem;
  }

  .card-grid {
    gap: 0.75rem;
  }

  .panel {
    padding: 1.1rem;
  }

  .tab {
    padding: 0.55rem 0.65rem;
    font-size: 0.85rem;
  }

  .evidence-card {
    padding: 0.9rem 1rem;
  }

  .limits-list li {
    gap: 0.7rem;
    padding: 0.9rem 1rem;
  }

  .code-card {
    padding: 1.1rem 1rem 1.15rem;
  }

  .code-card code {
    font-size: 0.8rem;
  }
}

@media (max-width: 520px) {
  .nav-links a {
    padding: 0.25rem 0.5rem;
    font-size: 0.88rem;
  }

  .wordmark {
    font-size: 1.05rem;
  }

  .corpus-table td {
    grid-template-columns: 4.5rem minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

@media print {
  .site-header,
  .copy-btn,
  .toggle-btn {
    display: none;
  }

  body {
    background: #fff;
  }

  .tab-panel,
  .panel,
  .table-card,
  .code-card {
    box-shadow: none;
  }

  .code-card,
  .code-card code {
    background: #fff;
    color: #000;
  }
}
